5	namespace Tests\Feature\Assets;
6	
7	use App\Models\Product;
8	use App\Models\User;
9	use AtrioTeam\DigitalHub\Assets\Filament\Pages\AssetManager;
10	use AtrioTeam\DigitalHub\Assets\Jobs\ProcessAssetJob;
11	use AtrioTeam\DigitalHub\Assets\Metadata\ExtractedMetadata;
12	use AtrioTeam\DigitalHub\Assets\Models\Media as TaggableMedia;
13	use AtrioTeam\DigitalHub\Assets\Support\AssetDuplicator;
14	use AtrioTeam\DigitalHub\Assets\Support\AssetPreview;
15	use AtrioTeam\DigitalHub\Assets\Support\AssetProcessingStatus;
16	use AtrioTeam\DigitalHub\Tags\Models\Tag;
17	use Filament\Facades\Filament;
18	use Illuminate\Foundation\Testing\RefreshDatabase;
19	use Illuminate\Support\Facades\Queue;
20	use Illuminate\Support\Facades\Storage;
21	use Livewire\Livewire;
22	use Tests\TestCase;
23	
24	/**
25	 * Duplicazione di un asset (digital-hub 14e): nuovo record Media con copia
26	 * fisica del file (stessi owner/disco/collection/folder), suffisso "(copia N)"
27	 * su `name` e (sanitizzato) su `file_name`, tag replicati; metadati/anteprima
28	 * non copiati — la copia riparte `pending` col job di rielaborazione in coda.
29	 */
30	class AssetDuplicateTest extends TestCase
31	{
32	    use RefreshDatabase;
33	
34	    public function test_duplicate_creates_new_record_with_copied_file_and_requeues_processing(): void
35	    {
36	        Storage::fake('assets');
37	        Queue::fake();
38	
39	        $user = User::factory()->create();
40	        $this->actingAs($user);
41	
42	        $product = Product::create(['name' => ['it' => 'Tavolo']]);
43	        $folder = $product->createAssetFolder('Schede');
44	        $media = $product
45	            ->addMediaFromString('contenuto originale')
46	            ->usingName('Scheda tecnica')
47	            ->usingFileName('scheda.txt')
48	            ->toMediaCollection('assets');
49	        $media->setAttribute('asset_folder_id', $folder->getKey());
50	
51	        // simula un asset già elaborato: metadati estratti + poster generato
52	        ExtractedMetadata::write($media, ['common' => ['size' => 19]]);
53	        $disk = Storage::disk('assets');
54	        $disk->put(AssetPreview::relativePath($media), 'poster');
55	        $media->setCustomProperty(AssetPreview::PROPERTY, AssetPreview::relativePath($media));
56	        $media->setAttribute('processing_status', AssetProcessingStatus::Completed->value);
57	        $media->save();
58	
59	        $copy = AssetDuplicator::duplicate($media);
60	
61	        // nuovo record: stesso owner/collection/folder; suffisso su name e
62	        // (sanitizzato, spazi → trattini) su file_name
63	        $this->assertNotSame($media->getKey(), $copy->getKey());
64	        $this->assertSame($media->model_type, $copy->model_type);
65	        $this->assertSame($media->model_id, $copy->model_id);
66	        $this->assertSame('assets', $copy->collection_name);
67	        $this->assertSame($folder->getKey(), $copy->getAttribute('asset_folder_id'));
68	        $this->assertSame('scheda-(copia).txt', $copy->file_name);
69	        $this->assertSame('Scheda tecnica (copia)', $copy->name);
70	
71	        // copia fisica: entrambi i file esistono, contenuto identico
72	        $disk->assertExists($media->getPathRelativeToRoot());
73	        $disk->assertExists($copy->getPathRelativeToRoot());
74	        $this->assertSame('contenuto originale', $disk->get($copy->getPathRelativeToRoot()));
75	
76	        // uploader = chi duplica; derivati non copiati, rielaborazione in coda
77	        $this->assertSame($user->getKey(), $copy->getAttribute('uploaded_by_id'));
78	        $this->assertSame([], ExtractedMetadata::forMedia($copy));
79	        $this->assertNull($copy->getCustomProperty(AssetPreview::PROPERTY));
80	        $this->assertSame(AssetProcessingStatus::Pending->value, $copy->getAttribute('processing_status'));
81	        Queue::assertPushed(ProcessAssetJob::class, fn (ProcessAssetJob $job): bool => $job->mediaId === $copy->getKey());
82	
83	        // l'originale resta intatto
84	        $media->refresh();
85	        $this->assertSame('Scheda tecnica', $media->name);
86	        $this->assertSame(AssetProcessingStatus::Completed->value, $media->getAttribute('processing_status'));
87	    }
88	
89	    public function test_copy_suffix_is_progressive_and_not_stacked(): void
90	    {
91	        Storage::fake('assets');
92	        Queue::fake();
93	
94	        $product = Product::create(['name' => ['it' => 'Tavolo']]);
95	        $media = $product
96	            ->addMediaFromString('contenuto')
97	            ->usingName('Doc')
98	            ->usingFileName('doc.txt')
99	            ->toMediaCollection('assets');
100	
101	        $first = AssetDuplicator::duplicate($media);
102	        $second = AssetDuplicator::duplicate($media);
103	        // duplicare una copia non accumula suffissi: "Doc (copia) (copia)" mai
104	        $third = AssetDuplicator::duplicate($first);
105	
106	        $this->assertSame('Doc (copia)', $first->name);
107	        $this->assertSame('Doc (copia 2)', $second->name);
108	        $this->assertSame('Doc (copia 3)', $third->name);
109	
110	        // stesso suffisso, sanitizzato, sul file_name (senza accumulo)
111	        $this->assertSame('doc-(copia).txt', $first->file_name);
112	        $this->assertSame('doc-(copia-2).txt', $second->file_name);
113	        $this->assertSame('doc-(copia-3).txt', $third->file_name);
114	    }
115	
116	    public function test_suffix_is_scoped_to_the_folder_of_the_original(): void
117	    {
118	        Storage::fake('assets');
119	        Queue::fake();
120	
121	        $product = Product::create(['name' => ['it' => 'Tavolo']]);
122	        $folder = $product->createAssetFolder('Schede');
123	
124	        // in root esiste già "Doc (copia)"; l'originale sta in una folder,
125	        // dove quel nome è libero
126	        $product->addMediaFromString('x')->usingName('Doc (copia)')->usingFileName('a.txt')->toMediaCollection('assets');
127	        $media = $product->addMediaFromString('y')->usingName('Doc')->usingFileName('b.txt')->toMediaCollection('assets');
128	        $media->setAttribute('asset_folder_id', $folder->getKey());
129	        $media->save();
130	
131	        $copy = AssetDuplicator::duplicate($media);
132	
133	        $this->assertSame('Doc (copia)', $copy->name);
134	        $this->assertSame($folder->getKey(), $copy->getAttribute('asset_folder_id'));
135	    }
136	
137	    public function test_duplicate_copies_tags(): void
138	    {
139	        Storage::fake('assets');
140	        Queue::fake();
141	
142	        $product = Product::create(['name' => ['it' => 'Tavolo']]);
143	        $media = $product
144	            ->addMediaFromString('contenuto')
145	            ->usingName('Doc')
146	            ->usingFileName('doc.txt')
147	            ->toMediaCollection('assets');
148	
149	        $tag = Tag::create(['name' => 'Rosso']);
150	        $this->assertInstanceOf(TaggableMedia::class, $media);
151	        $media->tags()->sync([$tag->getKey()]);
152	
153	        $copy = AssetDuplicator::duplicate($media);
154	
155	        $this->assertInstanceOf(TaggableMedia::class, $copy);
156	        $this->assertSame([$tag->getKey()], $copy->tags()->pluck('tags.id')->all());
157	    }
158	
159	    public function test_duplicate_action_is_wired_in_asset_manager(): void
160	    {
161	        Storage::fake('assets');
162	        Queue::fake();
163	
164	        $this->actingAs(User::factory()->create());
165	        Filament::setCurrentPanel('admin');
166	
167	        $product = Product::create(['name' => ['it' => 'Tavolo']]);
168	        $media = $product
169	            ->addMediaFromString('contenuto')
170	            ->usingName('Doc')
171	            ->usingFileName('doc.txt')
172	            ->toMediaCollection('assets');
173	
174	        Livewire::test(AssetManager::class, ['ownerType' => 'product', 'owner' => $product->getKey()])
175	            ->callAction('duplicateAsset', arguments: ['media' => $media->getKey()])
176	            ->assertHasNoActionErrors()
177	            ->assertOk();
178	
179	        $this->assertSame(2, $product->media()->where('collection_name', 'assets')->count());
180	        $this->assertNotNull($product->media()->where('name', 'Doc (copia)')->first());
181	    }
182	}
