use App\Models\Product;
use AtrioTeam\DigitalHub\Assets\Filament\Pages\AssetManager;
use Filament\Facades\Filament;
use Illuminate\Support\Facades\Storage;
use Livewire\Livewire;
$user = App\Models\User::factory()->create();
auth()->login($user);
Filament::setCurrentPanel("admin");
Storage::fake("assets");
$product = Product::create(["name" => ["it" => "Tavolo"]]);
$img = imagecreatetruecolor(40,25); ob_start(); imagejpeg($img); $data = ob_get_clean();
$media = $product->addMediaFromString($data)->usingFileName("photo.jpg")->toMediaCollection("assets");
$t = Livewire::test(AssetManager::class, ["ownerType"=>"product","owner"=>$product->getKey()])->mountAction("infoAsset", ["media"=>$media->getKey()]);
$page = $t->instance();
$action = $page->infoAssetAction();
$action->arguments(["media" => $media->getKey()]);
foreach ($action->getExtraModalFooterActions() as $a) {
  echo $a->getName()." -> ".$a->toHtml()."\n---\n";
}
' 2>&1 | tail -100

